#!/bin/sh
# OOXML test documents. They change on every run (dates, random ids), so they
# are not regenerated by this script:
#
# - doc.docx: a Word document made by LibreOffice from a text file (its
#   [Content_Types].xml is the last part of the package):
#
#     printf 'Hola autofirma-rs\nDocumento de prueba de firma.\n' > doc.txt
#     soffice --headless --convert-to docx doc.txt
#
# - autofirma-rsa.docx, autofirma-ec.docx: doc.docx signed by AutoFirma 1.9
#   (AOOOXMLSigner). It reads the screen size, so it needs a display:
#
#     J="java -cp /usr/lib/Autofirma/autofirma.jar ../../../tools/AfirmaMulti.java"
#     $J ../certs/rsa.p12 sign ooxml doc.docx autofirma-rsa.docx
#     $J ../certs/ec.p12 sign ooxml doc.docx autofirma-ec.docx
#
# Under the VS Code snap, run java with a clean environment that keeps the display
# (env -i PATH=/usr/bin:/bin HOME=$HOME DISPLAY=$DISPLAY XAUTHORITY=$XAUTHORITY ...).
exit 0
